"""QQ-姿态库：白模姿态参考图的多角度索引与取图。

内置素材随仓库分发（升级被覆盖是预期），**用户素材一律放在插件外面**：

    <ComfyUI>/user/QQ_ComfyUI_Tools/GuliPoses/pose/custom/   节点里「导入」的图
    <ComfyUI>/user/QQ_ComfyUI_Tools/GuliPoses/pose/png/      自己丢原始图，自动转 webp

目录位置由 ``user_root()`` 决定，可用环境变量 ``QQ_GULI_POSES_DIR`` 覆盖。
索引按目录签名缓存，导入/删除后不需要重启 ComfyUI。
"""

from __future__ import annotations

import json
import os
import threading
import uuid
from datetime import datetime
from pathlib import Path
from typing import Any

NODE_DIR = Path(__file__).resolve().parent
#: 内置姿态库素材（随仓库）。
BUILTIN_DIR = NODE_DIR / "guli_poses"

IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".webp", ".bmp")

#: 姿态库的五个视角；索引里用英文键，界面用中文标签。
ANGLE_LABELS = {"front": "正面", "high": "俯视", "low": "仰视", "side": "侧面", "diag": "斜侧"}
LABEL_TO_ANGLE = {label: key for key, label in ANGLE_LABELS.items()}
RANDOM_ANGLE = "随机视角"
ANGLE_CHOICES = list(ANGLE_LABELS.values()) + [RANDOM_ANGLE]

ALL = "全部"
CUSTOM_SERIES_KEY = "custom"
CUSTOM_SERIES_NAME = "我的姿态"
CUSTOM_CAT = "自定义"
EMPTY_HINT = "（库为空：请在节点里点「导入」放自己的图）"

THUMB_SIDE = 320
WEBP_QUALITY = 95

_log = print


class PoseDBMissing(RuntimeError):
    """库还没准备好（空库 / 索引缺失），或选中的姿态已经不在库里。"""


def user_root() -> Path:
    """用户素材根目录，永远在插件目录外面。"""
    env = (os.environ.get("QQ_GULI_POSES_DIR") or "").strip()
    if env:
        custom = Path(env).expanduser()
        return custom if custom.is_absolute() else (NODE_DIR / custom).resolve()
    try:
        import folder_paths

        base = folder_paths.get_user_directory()
    except Exception:
        base = None
    if base:
        return Path(base) / "QQ_ComfyUI_Tools" / "GuliPoses"
    return NODE_DIR / "userdata" / "GuliPoses"


USER_ROOT = user_root()


def lib_dir(lib: str = "pose") -> Path:
    """某个库的用户目录（插件外面）。"""
    return USER_ROOT / lib


def custom_dir(lib: str = "pose") -> Path:
    """节点「导入」落盘的位置。"""
    return lib_dir(lib) / "custom"


def raw_dir(lib: str = "pose") -> Path:
    """用户直接丢原始图的目录，自动转成 webp 并重建索引。"""
    return lib_dir(lib) / "png"


#: 各库的物理路径与角度集；加库只需在这里追加一项。
#: custom/ 三项由 :func:`_cfg` 按当前 USER_ROOT 现算，这里只放随仓库分发的路径。
LIB_DIRS: dict[str, dict[str, Any]] = {
    "pose": {
        "builtin": BUILTIN_DIR / "img",
        "index": BUILTIN_DIR / "index.json",
        "thumb": BUILTIN_DIR / "thumbs",
        "angles": ANGLE_LABELS,
        "name": "姿态库",
    },
}


def _cfg(lib: str = "pose") -> dict[str, Any]:
    """库路径配置；custom/ 相关项每次按当前 USER_ROOT 现算。

    不能把 custom 路径写死在 LIB_DIRS 里：测试会改 USER_ROOT，写死的话
    路径还指向旧目录（真实运行时也要支持 GULI 环境变量换盘）。
    """
    cfg = dict(LIB_DIRS[lib])
    custom = custom_dir(lib)
    cfg["custom"] = custom
    cfg["custom_thumb"] = custom / "thumbs"
    cfg["custom_meta"] = custom / "meta.json"
    return cfg


def lib_name(lib: str = "pose") -> str:
    """库的中文名，用于提示文案。"""
    return str(LIB_DIRS.get(lib, {}).get("name") or lib)


# ---------------------------------------------------------------------------
# 索引读取
# ---------------------------------------------------------------------------

_builtin_cache: dict[str, dict[str, Any]] = {}
_custom_cache: dict[str, dict[str, Any]] = {}
_lock = threading.Lock()


def _empty_base(angles: dict[str, str]) -> dict[str, Any]:
    return {
        "generated": None,
        "source": None,
        "angles": [{"key": key, "label": label} for key, label in angles.items()],
        "series": [],
        "poses": [],
    }


def builtin_index(lib: str = "pose") -> dict[str, Any]:
    """内置索引；文件缺失时按空库处理，只用自定义图也能开工。"""
    cfg = _cfg(lib)
    cache = _builtin_cache.setdefault(lib, {})
    try:
        mtime = cfg["index"].stat().st_mtime_ns
    except OSError:
        mtime = None
    if cache.get("index") is not None and cache.get("mtime") == mtime:
        return cache["index"]
    if mtime is None:
        data = _empty_base(cfg["angles"])
    else:
        try:
            data = json.loads(cfg["index"].read_text(encoding="utf-8"))
        except (OSError, ValueError) as err:
            _log(f"[QQ-姿态库] 索引读不出来，按空库处理：{err}")
            data = _empty_base(cfg["angles"])
        for key, default in _empty_base(cfg["angles"]).items():
            data.setdefault(key, default)
        for pose in data.get("poses", []):
            pose["lib"] = lib
            pose.setdefault("root", "builtin")
    cache["index"] = data
    cache["mtime"] = mtime
    return data


# ---------------------------------------------------------------------------
# 原始图自动转换
# ---------------------------------------------------------------------------


def _convert_to_webp(src: Path, dst: Path) -> None:
    from PIL import Image, ImageOps

    try:
        if dst.is_file() and dst.stat().st_mtime_ns >= src.stat().st_mtime_ns:
            return
    except OSError:
        pass
    dst.parent.mkdir(parents=True, exist_ok=True)
    tmp = dst.with_name(f"{dst.name}.{uuid.uuid4().hex[:8]}.tmp")
    try:
        with Image.open(src) as im:
            im = ImageOps.exif_transpose(im).convert("RGB")
            im.save(tmp, "WEBP", quality=WEBP_QUALITY, method=4)
        tmp.replace(dst)
    except OSError:
        tmp.unlink(missing_ok=True)
        raise


def auto_build(lib: str = "pose") -> None:
    """把 png/ 里的原始图转成内置目录下的 webp 并重建索引。幂等。"""
    cfg = _cfg(lib)
    raw = raw_dir(lib)
    try:
        raw.mkdir(parents=True, exist_ok=True)
    except OSError:
        return
    sources: list[Path] = []
    try:
        for entry in os.scandir(raw):
            if not entry.is_file():
                continue
            suffix = Path(entry.name).suffix.lower()
            if suffix in IMAGE_EXTS and suffix != ".webp":
                sources.append(Path(entry.path))
    except OSError:
        return
    if not sources:
        return
    img_dir = cfg["builtin"]
    for src in sources:
        try:
            _convert_to_webp(src, img_dir / f"{src.stem}.webp")
        except Exception as err:  # 单张坏图不影响其它
            _log(f"[QQ-姿态库] 转换失败 {src.name}：{err}")
    _rebuild_index(lib)


def _rebuild_index(lib: str) -> None:
    """以内置 img/*.webp 为准重建 index.json（仅在自动建库时使用）。"""
    cfg = _cfg(lib)
    img_dir = cfg["builtin"]
    webs = sorted(img_dir.glob("*.webp"))
    if not webs:
        return
    poses = []
    for im in webs:
        stem = im.stem
        poses.append(
            {
                "no": f"default/{stem}",
                "root": "builtin",
                "series": "default",
                "code": stem,
                "cat": "姿态",
                "name": stem,
                "angles": {"front": {"img": f"{stem}.webp", "thumb": f"{stem}.jpg"}},
                "label": f"姿态 {stem}",
                "lib": lib,
            }
        )
    index = {
        "generated": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "source": "auto-built from raw images",
        "series": [{"key": "default", "name": "姿态", "short": "姿态", "count": len(poses)}],
        "angles": [{"key": key, "label": label} for key, label in cfg["angles"].items()],
        "poses": poses,
    }
    cfg["index"].parent.mkdir(parents=True, exist_ok=True)
    tmp = cfg["index"].with_name(f"{cfg['index'].name}.{uuid.uuid4().hex[:8]}.tmp")
    try:
        tmp.write_text(json.dumps(index, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
        tmp.replace(cfg["index"])
    except OSError:
        tmp.unlink(missing_ok=True)
        raise
    _builtin_cache.pop(lib, None)


# ---------------------------------------------------------------------------
# 自定义图（用户导入）
# ---------------------------------------------------------------------------


def _custom_files(lib: str = "pose") -> list[tuple[str, int, int]]:
    cfg = _cfg(lib)
    try:
        with os.scandir(cfg["custom"]) as entries:
            found = []
            for entry in entries:
                if not entry.is_file():
                    continue
                if Path(entry.name).suffix.lower() not in IMAGE_EXTS:
                    continue
                stat = entry.stat()
                found.append((entry.name, stat.st_size, int(stat.st_mtime)))
    except OSError:
        return []
    return sorted(found)


def _make_thumb(src: Path, dst: Path) -> None:
    from PIL import Image, ImageOps

    with Image.open(src) as im:
        im = ImageOps.exif_transpose(im)
        if im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info):
            rgba = im.convert("RGBA")
            flat = Image.new("RGB", rgba.size, (255, 255, 255))
            flat.paste(rgba, mask=rgba.split()[-1])
            im = flat
        else:
            im = im.convert("RGB")
        im.thumbnail((THUMB_SIDE, THUMB_SIDE), Image.LANCZOS)
        dst.parent.mkdir(parents=True, exist_ok=True)
        im.save(dst, "JPEG", quality=86, optimize=True)


def ensure_thumb(name: str, lib: str = "pose", custom: bool = False) -> Path | None:
    """缩略图路径；没有就用原图现生成一张。"""
    cfg = _cfg(lib)
    file_name = Path(str(name or "")).name
    if not file_name:
        return None
    if custom:
        source = cfg["custom"] / file_name
        if not source.is_file():
            return None
        target = cfg["custom_thumb"] / f"{source.stem}.jpg"
        if target.is_file():
            try:
                if target.stat().st_mtime_ns >= source.stat().st_mtime_ns:
                    return target
            except OSError:
                pass
    else:
        target = cfg["thumb"] / file_name
        if target.is_file():
            return target
        stem = Path(file_name).stem
        source = next(
            (p for ext in IMAGE_EXTS if (p := cfg["builtin"] / f"{stem}{ext}").is_file()), None
        )
        if source is None:
            return None
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        tmp = target.with_name(f"{target.name}.{uuid.uuid4().hex[:8]}.tmp")
        _make_thumb(source, tmp)
        tmp.replace(target)
    except Exception:
        return None
    return target


def _load_meta(lib: str = "pose") -> dict[str, Any]:
    cfg = _cfg(lib)
    try:
        data = json.loads(cfg["custom_meta"].read_text(encoding="utf-8"))
        return data.get("items") or {}
    except Exception:
        return {}


def _write_meta(items: dict[str, Any], lib: str = "pose") -> None:
    cfg = _cfg(lib)
    cfg["custom"].mkdir(parents=True, exist_ok=True)
    cfg["custom_meta"].write_text(
        json.dumps({"version": 1, "items": items}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def _split_angle(stem: str, angles: dict[str, str]) -> tuple[str, str]:
    """从文件名尾部剥离视角标记：``姿势A_side`` → ``(姿势A, side)``。"""
    hints = {
        "front": "front", "正面": "front",
        "side": "side", "侧面": "side",
        "high": "high", "俯视": "high", "top": "high",
        "low": "low", "仰视": "low",
        "diag": "diag", "斜侧": "diag",
    }
    low = stem.lower()
    default = "front" if "front" in angles else next(iter(angles))
    for token, key in hints.items():
        for sep in ("_", "-", " ", "·"):
            suffix = (sep + token).lower()
            if low.endswith(suffix) and len(stem) > len(suffix):
                return stem[: -len(suffix)].strip(" _-·"), (key if key in angles else default)
    return stem, default


def _scan_custom(lib: str = "pose") -> list[dict[str, Any]]:
    """扫描 custom/ 生成姿态记录；同名同分类的多个视角归并成一条。"""
    cfg = _cfg(lib)
    angles = cfg["angles"]
    cache = _custom_cache.setdefault(lib, {})
    files = _custom_files(lib)
    sig = tuple(files)
    if cache.get("poses") is not None and cache.get("sig") == sig:
        return cache["poses"]
    meta = _load_meta(lib)
    groups: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for name, _size, mtime in files:
        entry = meta.get(name) or {}
        if entry.get("name"):
            display = str(entry["name"])[:60]
            angle = entry.get("angle") if entry.get("angle") in angles else "front"
        else:
            display, angle = _split_angle(Path(name).stem, angles)
            display = display[:60] or Path(name).stem
        cat = str(entry.get("cat") or CUSTOM_CAT)[:60]

        thumb_name = f"{Path(name).stem}.jpg"
        thumb_path = cfg["custom_thumb"] / thumb_name
        try:
            if not thumb_path.is_file() or int(thumb_path.stat().st_mtime) < mtime:
                _make_thumb(cfg["custom"] / name, thumb_path)
        except Exception:
            continue  # 坏图不进库，免得选了才报错

        key = display
        if key in groups and angle in groups[key]["angles"]:
            seq = 2
            while f"{display} ({seq})" in groups:
                seq += 1
            key = f"{display} ({seq})"
        slot = groups.setdefault(key, {"cat": cat, "angles": {}})
        slot["angles"][angle] = {"img": name, "thumb": thumb_name}
        if key not in order:
            order.append(key)

    poses = []
    for idx, key in enumerate(order, 1):
        slot = groups[key]
        ang = {a: slot["angles"][a] for a in angles if a in slot["angles"]}
        poses.append(
            {
                "no": f"{CUSTOM_SERIES_KEY}/{key}",
                "lib": lib,
                "root": CUSTOM_SERIES_KEY,
                "series": CUSTOM_SERIES_KEY,
                "code": f"C{idx:03d}",
                "cat": slot["cat"],
                "name": key,
                "angles": ang,
                "label": f"{CUSTOM_SERIES_NAME} · {key}",
            }
        )
    with _lock:
        cache["poses"] = poses
        cache["sig"] = sig
    return poses


def index(lib: str = "pose") -> dict[str, Any]:
    """内置库 + 自定义库合并后的索引；自定义排在最前面。"""
    auto_build(lib)
    base = builtin_index(lib)
    custom_poses = _scan_custom(lib)
    if not custom_poses:
        return base
    merged = dict(base)
    merged["poses"] = list(custom_poses) + list(base.get("poses") or [])
    merged["series"] = (
        [{"key": CUSTOM_SERIES_KEY, "name": CUSTOM_SERIES_NAME, "short": "我的",
          "count": len(custom_poses)}]
        + list(base.get("series") or [])
    )
    merged["customCount"] = len(custom_poses)
    return merged


# ---------------------------------------------------------------------------
# 下拉选项
# ---------------------------------------------------------------------------


def pose_labels(lib: str = "pose") -> list[str]:
    return [pose["label"] for pose in index(lib)["poses"]]


def series_options(lib: str = "pose") -> list[str]:
    return [ALL] + [series["name"] for series in index(lib)["series"]]


def category_options(lib: str = "pose") -> list[str]:
    data = index(lib)
    order = {s["key"]: i for i, s in enumerate(data.get("series", []))}
    counts: dict[str, int] = {}
    series_of: dict[str, str] = {}
    for pose in data["poses"]:
        cat = pose["cat"]
        counts[cat] = counts.get(cat, 0) + 1
        series_of[cat] = pose.get("series", "")
    return [ALL] + sorted(
        counts, key=lambda cat: (order.get(series_of.get(cat), 99), -counts[cat], cat)
    )


def angle_choices(lib: str = "pose") -> list[str]:
    labels = list(_cfg(lib)["angles"].values())
    return labels + [RANDOM_ANGLE] if len(labels) > 1 else labels


# ---------------------------------------------------------------------------
# 取图
# ---------------------------------------------------------------------------


def find_pose(label: str, lib: str = "pose") -> dict[str, Any]:
    poses = index(lib)["poses"]
    for pose in poses:
        if pose["label"] == label:
            return pose
    raise PoseDBMissing(
        f"库里没有「{label}」这一项。\n"
        "它可能已被删除或改名，请在节点里重新选一个姿态。"
    )


def series_key(name: str | None, lib: str = "pose") -> str | None:
    for series in index(lib)["series"]:
        if series["name"] == name:
            return series["key"]
    return None


def pool(series_name: str | None = None, category: str = ALL, lib: str = "pose"):
    """范围内随机的候选集；组合为空时逐级退化，避免节点直接报错。"""
    poses = index(lib)["poses"]
    if not poses:
        raise PoseDBMissing(
            f"{lib_name(lib)}是空的，没法抽图。\n"
            "可以在节点里点「导入」把自己的图放进来。"
        )
    key = None if series_name in (None, ALL) else series_key(series_name, lib)
    if key is not None:
        in_series = [pose for pose in poses if pose.get("series") == key]
        if category and category != ALL:
            matched = [pose for pose in in_series if pose["cat"] == category]
            if matched:
                return matched
        if in_series:
            return in_series
    if category and category != ALL:
        matched = [pose for pose in poses if pose["cat"] == category]
        if matched:
            return matched
    return poses


def pick_angle(pose: dict[str, Any], angle_label: str, rng) -> str:
    if angle_label == RANDOM_ANGLE:
        available = [key for key in ANGLE_LABELS if key in pose["angles"]]
        return rng.choice(available) if available else "front"
    return LABEL_TO_ANGLE.get(angle_label, "front")


def resolve(pose: dict[str, Any], angle_key: str) -> tuple[dict[str, Any], str, Path]:
    """返回 ``(姿态记录, 实际角度, 图片路径)``；缺图时按 正面→其余角度 回退。"""
    lib = str(pose.get("lib") or "pose")
    cfg = _cfg(lib)
    custom = pose.get("root") == CUSTOM_SERIES_KEY
    base = cfg["custom"] if custom else cfg["builtin"]
    order = [angle_key, "front"] + [k for k in cfg["angles"] if k not in (angle_key, "front")]
    for key in order:
        entry = pose["angles"].get(key)
        if not entry:
            continue
        path = base / entry["img"]
        if path.is_file():
            return pose, key, path
    raise FileNotFoundError(
        f"姿态图文件缺失：{pose['no']}（找过 {angle_key}、正面等角度）。"
    )


# ---------------------------------------------------------------------------
# 导入 / 删除（供路由使用）
# ---------------------------------------------------------------------------


def safe_filename(raw: str) -> str:
    illegal = '\\/:*?"<>|'
    name = Path(str(raw or "").replace("\\", "/")).name
    stem = Path(name).stem.strip(" .")
    ext = Path(name).suffix.lower()
    if ext not in IMAGE_EXTS:
        ext = ".png"
    stem = "".join(ch for ch in stem if ch not in illegal and ord(ch) >= 32).strip(" .")
    if not stem:
        stem = "姿态"
    return stem[:60] + ext


def save_custom(
    filename: str, data: bytes, name: str | None = None, cat: str | None = None,
    angle: str | None = None, lib: str = "pose",
) -> str:
    """写入一张自定义图并记进 meta.json，返回落盘后的文件名。"""
    cfg = _cfg(lib)
    safe = safe_filename(filename)
    cfg["custom"].mkdir(parents=True, exist_ok=True)
    stem, ext = Path(safe).stem, Path(safe).suffix
    target, dup = cfg["custom"] / safe, 2
    while target.exists():
        target = cfg["custom"] / f"{stem} ({dup}){ext}"
        dup += 1
    target.write_bytes(data)
    display = (name or "").strip() or stem
    items = dict(_load_meta(lib))
    items[target.name] = {
        "name": display[:60],
        "cat": (cat or CUSTOM_CAT)[:60],
        "angle": angle if angle in cfg["angles"] else "front",
    }
    _write_meta(items, lib)
    _custom_cache.setdefault(lib, {})["sig"] = None
    return target.name


def delete_custom(filename: str, lib: str = "pose") -> bool:
    """删掉 custom/ 里的一张图，连缩略图与 meta 记录一起清掉。"""
    cfg = _cfg(lib)
    target = (cfg["custom"] / Path(str(filename or "")).name).resolve()
    if target.parent != cfg["custom"].resolve() or not target.is_file():
        return False
    try:
        target.unlink()
    except OSError:
        return False
    try:
        (cfg["custom_thumb"] / f"{target.stem}.jpg").unlink()
    except OSError:
        pass
    items = dict(_load_meta(lib))
    if items.pop(target.name, None) is not None:
        _write_meta(items, lib)
    _custom_cache.setdefault(lib, {})["sig"] = None
    return True


def custom_count(lib: str = "pose") -> int:
    return len(_scan_custom(lib))


def custom_nos(names, lib: str = "pose") -> list:
    poses = _scan_custom(lib)
    owner = {}
    for pose in poses:
        for entry in pose["angles"].values():
            owner[entry["img"]] = pose["no"]
    return [owner.get(name) for name in names]
